/**
 * Confluence Node - Version 1
 * Discriminator: resource=page, operation=addComment
 */


interface Credentials {
  confluenceCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** Add a footer comment to a page, or reply to an existing comment */
export type ConfluenceV1PageAddCommentParams = {
  resource: 'page';
  operation: 'addComment';
  authentication?: 'cloudOAuth2' | 'serviceAccount';
/**
 * The Confluence site to use. Can be left empty when the connection has access to exactly one site.
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * Leave empty to comment directly on a page. Set to reply to an existing footer comment; the page is inferred from the parent.
 */
    parentCommentId?: string | Expression<string>;
/**
 * Limits page selection and By Title lookups to one space. Leave empty or pick "All Spaces" to search across all spaces.
 * @searchListMethod searchSpacesWithAll
 * @displayOptions.hide { parentCommentId: [{"_cnd":{"regex":"\\S"}}] }
 * @default {"mode":"list","value":""}
 */
    space?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The page to comment on
 * @searchListMethod getPages
 * @displayOptions.hide { parentCommentId: [{"_cnd":{"regex":"\\S"}}] }
 * @default {"mode":"list","value":""}
 */
    page?: { __rl: true; mode: 'list' | 'url' | 'id' | 'title'; value: string; cachedResultName?: string };
/**
 * How the comment content below is interpreted
 * @default plainText
 */
    bodyFormat?: 'atlas_doc_format' | 'plainText' | 'storage' | Expression<string>;
/**
 * Comment content as plain text; each line becomes a paragraph. Blank lines and leading whitespace are removed.
 * @displayOptions.show { bodyFormat: ["plainText"] }
 */
    bodyPlainText?: string | Expression<string>;
/**
 * Comment content in Confluence storage format
 * @displayOptions.show { bodyFormat: ["storage"] }
 */
    bodyStorage?: string | Expression<string>;
/**
 * Comment content as an Atlassian Document Format document
 * @displayOptions.show { bodyFormat: ["atlas_doc_format"] }
 */
    bodyAdf?: IDataObject | string | Expression<string>;
};

export type ConfluenceV1PageAddCommentNode = {
  type: 'n8n-nodes-base.confluence';
  version: 1;
  config: NodeConfig<ConfluenceV1PageAddCommentParams> & { credentials?: Credentials };
};